import java.util.Set;

public class SortUtil {

    private static final Set<String> SORTABLE_FIELDS =
            Set.of("created_at", "likes", "title", "author_name");

    private static final Set<String> SORT_DIRECTIONS =
            Set.of("asc", "desc");

    public static String buildOrderClause(String sortParam) {
        String[] parts = sortParam.split(":", 2);

        String field = parts[0];
        String direction = parts.length > 1 ? parts[1] : "asc";

        if (!SORTABLE_FIELDS.contains(field)) {
            throw new IllegalArgumentException("Cannot sort by " + field);
        }

        if (!SORT_DIRECTIONS.contains(direction.toLowerCase())) {
            throw new IllegalArgumentException("Invalid sort direction");
        }

        return field + " " + direction.toUpperCase();
    }

    public static void main(String[] args) {
        System.out.println(buildOrderClause("likes:desc"));
        // Output: likes DESC

        System.out.println(buildOrderClause("title"));
        // Output: title ASC
    }
}

