# What you want to express:
# posts where (category = 'tech' OR likes > 1000) AND author_id IN (1,2,3)

# Hard to express cleanly in query params
# ?category=tech&min_likes=1000   -- this is AND, not OR

# GraphQL handles it naturally:
query {
  posts(
    where: {
      OR: [
        { category: { eq: "tech" } }
        { likes: { gt: 1000 } }
      ]
      author_id: { in: [1, 2, 3] }
    }
  ) { id title }
}

